// 根据音素时间戳驱动 blendshape
function driveMouthShape(phonemes, currentTime) {
  const active = phonemes.find(p =>
    currentTime >= p.start && currentTime <= p.end
  );
  return active
    ? { viseme: PHONEME_TO_VISEME[active.phone], weight: 1.0 }
    : { viseme: 'rest', weight: 0.0 };
}

// RAG 检索 + 生成的简化流程
async function emergencyQA(query, history) {
  // 1. 向量检索
  const embedding = await getEmbedding(query);
  const candidates = await milvus.search(
    'emergency_plans', embedding, { top_k: 10 }
  );
  // 2. 重排序
  const reranked = await reranker.rerank(query, candidates, { top_k: 3 });
  // 3. 构建 prompt
  const context = reranked.map(c =>
    `[来源:${c.source} §${c.section}]
${c.content}`
  ).join('\n---\n');
  // 4. LLM 生成
  return llm.chat({
    messages: [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: `参考资料：
${context}

用户问题：${query}

请按[立即执行]/[后续跟进]/[信息收集]分类回答，并注明出处。` }
    ]
  });
}

// 分段生成 + 审核流水线
async function generateArticle(topic, outline) {
  const sections = [];
  const factChecker = new LLM('claude-sonnet-4-6');
  const writer = new LLM('gpt-4o');
  for (const section of outline.sections) {
    // 生成草稿
    const draft = await writer.chat({
      messages: [{
        role: 'system',
        content: `你是一个专业的内容写手。请根据大纲撰写以下段落。
要求：200-300字、包含数据支撑、语气专业且易懂。`
      }, {
        role: 'user',
        content: `主题：${topic}
段落大纲：${section.outline}
已写内容（前文摘要）：${lastNSections(sections, 2)}`
      }]
    });
    // 事实核查
    const check = await factChecker.chat({
      messages: [{
        role: 'system',
        content: '检查以下内容的事实准确性，标记任何存疑的陈述。用 JSON 返回：[{claim, verdict:OK|DUBIOUS|WRONG, correction}]。'}, {
        role: 'user', content: draft
      }]
    });
    sections.push({ draft, factCheck: JSON.parse(check) });
  }
  return sections;
}

// ControlNet + SD 图像生成流程
async function generateProductImage(originalImg, styleDesc) {
  // 1. 背景移除 + 主体提取
  const mask = await SAM.predict(originalImg);
  const subject = applyMask(originalImg, mask);
  // 2. 提取 canny 边缘（保持产品轮廓不变）
  const canny = await controlnetCanny.process(originalImg);
  // 3. 风格 prompt 构建
  const stylePrompt = await llm.translate(styleDesc);
  // 4. Stable Diffusion 生成
  const result = await sd.txt2img({
    prompt: `${stylePrompt}, product photography, 8k, studio lighting`,
    negative_prompt: 'blurry, distorted, watermark, text',
    controlnet: { input: canny, model: 'canny', weight: 0.8 },
    width: 800, height: 800, num_images: 6
  });
  return result.images;
}

// 多 Agent 路由编排
class PaymentCSRouter {
  async handle(userMsg, history) {
    // 1. 意图路由
    const intent = await this.router.classify(userMsg);
    if (intent.confidence < 0.7) {
      return this.fallback.clarify(userMsg);
    }
    // 2. 根据意图选择检索策略
    let docs;
    switch (intent.category) {
      case 'FAQ':
        docs = await this.retriever.vectorSearch(userMsg, { topK: 5, collection: 'qa' });
        break;
      case 'POLICY':
        docs = await this.retriever.hybridSearch(userMsg, { topK: 8, bm25Weight: 0.3 });
        break;
      case 'TECH':
        docs = await this.retriever.structuredQuery(userMsg, { index: 'error_codes' });
        break;
      default:
        docs = await this.retriever.vectorSearch(userMsg, { topK: 5 });
    }
    // 3. 生成回答
    return this.generator.generate(userMsg, docs, history, intent);
  }
}

