// 自然语言指令 → 结构化任务
async function parseMowingCommand(asrText, semanticMap) {
  // 1. LLM 理解
  const nlu = await llm.chat({
    messages: [{
      role: 'system',
      content: '解析用户的割草指令，输出 JSON: {intent, target_zones:[], forbidden_objects:[], constraints:[]}'
    }, { role: 'user', content: asrText }]
  });
  const task = JSON.parse(nlu);
  // 2. 空间映射：自然语言 → 坐标
  task.target_zones = task.target_zones.map(z =>
    semanticMap.findZone(z));  // "前院" → {zone_id:3, polygon:[...]}
  task.forbidden_objects = task.forbidden_objects.map(o =>
    semanticMap.findObject(o)); // "玫瑰花坛" → {obj_id:7, polygon:[...]}
  // 3. 路径规划
  const path = pathPlanner.plan({
    target: task.target_zones,
    forbidden: task.forbidden_objects,
    safetyMargin: 0.3  // 花坛周围 30cm 安全距离
  });
  return { task, path };
}

