# 字幕提取 + 时序聚合（Python 伪代码）
def extract_subtitles(video_path):
    frames = cv2_extract_frames(video_path, fps=2)  # 每秒2帧
    ocr_results = []
    for t, frame in frames:
        boxes = paddleocr.detect_text(frame)
        for box, text in boxes:
            ocr_results.append({'time': t, 'box': box, 'text': text})
    # 时序聚合：同一位置的文字合并
    subtitles = temporal_merge(ocr_results,
        iou_threshold=0.8,      # 位置重叠度 >80% 认为是同一字幕
        max_gap=0.5             # 间隔 <0.5s 合并
    )
    return to_srt(subtitles)

// TTS 统一调用适配层
class TTSAdapter {
  async synthesize(text, voiceProfileId, options = {}) {
    const cacheKey = `${voiceProfileId}:${hash(text)}`;
    // 1. 查缓存
    const cached = await redis.get(cacheKey);
    if (cached) return cached;
    // 2. 根据 voice profile 路由到具体引擎
    const profile = await this.getProfile(voiceProfileId);
    let audio;
    try {
      switch (profile.engine) {
        case 'volcano':
          audio = await this.volcanoTTS.synthesize(text, profile.voiceId, options);
          break;
        case 'azure':
          audio = await this.azureTTS.synthesize(text, profile.voiceId, options);
          break;
        case 'vits_selfhost':
          audio = await this.selfHostTTS.synthesize(text, profile.modelId, options);
          break;
      }
    } catch (err) {
      // 3. 失败降级：自研挂了用商业
      if (profile.engine === 'vits_selfhost') {
        audio = await this.volcanoTTS.synthesize(text, profile.fallbackVoiceId, options);
      } else throw err;
    }
    await redis.setex(cacheKey, 86400, audio); // 缓存 24h
    return audio;
  }
}

// 口型驱动多级兜底
async function driveLipSync(ttsResult, avatarModel) {
  try {
    // 主路径：音素驱动的精确口型
    if (ttsResult.phonemes && ttsResult.phonemes.length > 0) {
      return await phonemeBlendshape(ttsResult.phonemes, avatarModel);
    }
    // 一级兜底：音频音量包络驱动
    const rms = computeRMSEnvelope(ttsResult.audio);
    return await energyBlendshape(rms, avatarModel);
  } catch (err) {
    if (err.code === 'GPU_OOM') {
      // 二级兜底：切换 2D 模式
      return await fallbackTo2D(ttsResult.audio, avatarModel.staticImage);
    }
    // 三级兜底：降级渲染质量重试
    return await driveLipSync(ttsResult, avatarModel, { lowQuality: true });
  }
}

# 灵活性-成本决策矩阵（Python 示例）
def decide_deployment(requirement):
    """
    requirement: {flexibility, monthlyVolume, latencyReq, customizationNeed}
    returns: 'api' | 'managed' | 'selfhost'
    """
    if requirement['customizationNeed'] == 'high':
        return 'selfhost'  # 高定制需求 → 必须自部署
    apiCost = requirement['monthlyVolume'] * API_UNIT_PRICE
    selfhostCost = GPU_MONTHLY + ENGINEER_SALARY * 0.3
    if apiCost < selfhostCost * 0.6:  # API 成本低于自部署 60%
        return 'api'
    elif requirement['flexibility'] == 'high':
        return 'selfhost'
    else:
        return 'managed'  # 中间状态选托管服务
